-- EIGHT SKY SWITCHER V6 (PlayerGui FIX) | Pink Bliss / Cool Black / Breakcore / Alya Flushie
-- Delta/iPad | select a sky without rejoining. Uses only local visual changes.
local Lighting=game:GetService('Lighting')
local G=getcustomasset or getsynasset
local Http=game
local env=(getgenv and getgenv()) or _G
if env.FourSkySwitcher and env.FourSkySwitcher.Close then pcall(env.FourSkySwitcher.Close) end
local state={active=nil, closed=false, busy=false, cache={}, serial=0}
env.FourSkySwitcher=state
local faces={'Bk','Dn','Ft','Lf','Rt','Up'}
local urls={
 PinkBliss={Bk='https://raw.githubusercontent.com/slappy64/pink-for-bliss/main/sky512_bk.tex',Dn='https://raw.githubusercontent.com/slappy64/pink-for-bliss/main/sky512_dn.tex',Ft='https://raw.githubusercontent.com/slappy64/pink-for-bliss/main/sky512_ft.tex',Lf='https://raw.githubusercontent.com/slappy64/pink-for-bliss/main/sky512_lf.tex',Rt='https://raw.githubusercontent.com/slappy64/pink-for-bliss/main/sky512_rt.tex',Up='https://raw.githubusercontent.com/slappy64/pink-for-bliss/main/sky512_up.tex'},
 AlyaFlushie={Bk='https://github.com/Ankkouu/flushie/raw/refs/heads/main/bk.tex',Dn='https://github.com/Ankkouu/flushie/raw/refs/heads/main/dn.tex',Ft='https://github.com/Ankkouu/flushie/raw/refs/heads/main/ft.tex',Lf='https://github.com/Ankkouu/flushie/raw/refs/heads/main/lt.tex',Rt='https://github.com/Ankkouu/flushie/raw/refs/heads/main/rt.tex',Up='https://github.com/Ankkouu/flushie/raw/refs/heads/main/up.tex'}
}
local BREAKCORE_B64=[==[]==]
local MAKIMA_B64={
 Bk=[==[]==],
 Dn=[==[]==],
 Ft=[==[]==],
 Lf=[==[]==],
 Rt=[==[]==],
 Up=[==[]==],
}
local ALYAV3_B64={
 Bk=[==[]==],
 Dn=[==[]==],
 Ft=[==[]==],
 Lf=[==[]==],
 Rt=[==[]==],
 Up=[==[]==],
}
local NAZUNA_B64={
 Bk=[==[]==],
 Dn=[==[]==],
 Ft=[==[]==],
 Lf=[==[]==],
 Rt=[==[]==],
 Up=[==[]==],
}
local alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
local lookup={} for i=1,#alphabet do lookup[alphabet:sub(i,i)]=i-1 end
local MAHIRU_B64={
 Bk=[==[]==],
 Dn=[==[]==],
 Ft=[==[]==],
 Lf=[==[]==],
 Rt=[==[]==],
 Up=[==[]==],
}
local function decode(s)
 local out={}
 for i=1,#s,4 do
  local a=lookup[s:sub(i,i)] or 0; local b=lookup[s:sub(i+1,i+1)] or 0
  local c=lookup[s:sub(i+2,i+2)]; local d=lookup[s:sub(i+3,i+3)]
  local v=a*262144+b*4096+(c or 0)*64+(d or 0)
  out[#out+1]=string.char(math.floor(v/65536)%256)
  if c then out[#out+1]=string.char(math.floor(v/256)%256) end
  if d then out[#out+1]=string.char(v%256) end
 end
 return table.concat(out)
end
local function fileAsset(key,bytes)
 if not writefile or not G then return nil,'Delta file/custom asset API unavailable' end
 local ext=bytes:sub(1,3)=='\255\216\255' and '.jpg' or bytes:sub(1,4)=='RIFF' and '.webp' or '.png'
 local path='four_sky_'..key..ext
 local ok,err=pcall(writefile,path,bytes); if not ok then return nil,tostring(err) end
 local yes,asset=pcall(G,path); if not yes then return nil,tostring(asset) end
 return asset
end
local function assetsFor(name)
 if state.cache[name] then return state.cache[name] end
 local result={}
 if name=='CoolBlack' then
  for _,f in ipairs(faces) do result[f]='rbxassetid://7658055825' end
 elseif name=='MahiruPoster' then
  for _,f in ipairs(faces) do
   local asset,err=fileAsset('MahiruPoster'..f,decode(MAHIRU_B64[f])); if not asset then return nil,err end
   result[f]=asset
  end
 elseif name=='AlyaV3' then
  for _,f in ipairs(faces) do
   local asset,err=fileAsset('AlyaV3'..f,decode(ALYAV3_B64[f])); if not asset then return nil,err end
   result[f]=asset
  end
 elseif name=='Nazuna' then
  for _,f in ipairs(faces) do
   local asset,err=fileAsset('Nazuna'..f,decode(NAZUNA_B64[f])); if not asset then return nil,err end
   result[f]=asset
  end
 elseif name=='Makima' then
  for _,f in ipairs(faces) do
   local asset,err=fileAsset('Makima'..f,decode(MAKIMA_B64[f])); if not asset then return nil,err end
   result[f]=asset
  end
 elseif name=='Breakcore' then
  local asset,err=fileAsset('breakcore',decode(BREAKCORE_B64)); if not asset then return nil,err end
  for _,f in ipairs(faces) do result[f]=asset end
 else
  for _,f in ipairs(faces) do
   local ok,bytes=pcall(function() return Http:HttpGet(urls[name][f]) end)
   if not ok or type(bytes)~='string' or #bytes<64 then return nil,'Failed to download '..f end
   local asset,err=fileAsset(name..f,bytes); if not asset then return nil,err end
   result[f]=asset
  end
 end
 state.cache[name]=result
 return result
end
local function putSky(name)
 if state.closed or not state.active or name~=state.active then return end
 local a=state.cache[name]; if not a then return end
 local sky=Instance.new('Sky'); sky.Name='FourSkySwitcher_'..name
 for _,f in ipairs(faces) do sky['Skybox'..f]=a[f] end
 for _,v in ipairs(Lighting:GetChildren()) do if v:IsA('Sky') then v:Destroy() end end
 sky.Parent=Lighting
end
-- V2: Parent to PlayerGui first (CoreGui may accept parenting but not render in Delta).
local Players=game:GetService('Players')
local player=Players.LocalPlayer
if not player then warn('[Sky Switcher V6] LocalPlayer missing'); return end
local playerGui=player:WaitForChild('PlayerGui',15)
if not playerGui then warn('[Sky Switcher V6] PlayerGui unavailable'); return end
local old=playerGui:FindFirstChild('FourSkySwitcherGUI')
if old then old:Destroy() end
local gui=Instance.new('ScreenGui')
gui.Name='FourSkySwitcherGUI'
gui.ResetOnSpawn=false
gui.IgnoreGuiInset=false
gui.DisplayOrder=10000
gui.ZIndexBehavior=Enum.ZIndexBehavior.Sibling
gui.Enabled=true
gui.Parent=playerGui
local frame=Instance.new('Frame'); frame.ZIndex=10; frame.Name='Menu'; frame.Size=UDim2.fromOffset(240,430); frame.Position=UDim2.new(0,20,.3,0); frame.BackgroundColor3=Color3.fromRGB(24,24,34); frame.BorderSizePixel=0; frame.Active=true; frame.Draggable=true; frame.Visible=true; frame.Parent=gui
Instance.new('UICorner',frame).CornerRadius=UDim.new(0,12)
local title=Instance.new('TextLabel'); title.BackgroundTransparency=1; title.Size=UDim2.new(1,-44,0,38); title.Position=UDim2.fromOffset(12,3); title.Font=Enum.Font.GothamBold; title.TextSize=17; title.TextColor3=Color3.new(1,1,1); title.TextXAlignment=Enum.TextXAlignment.Left; title.Text='🌌 SKY SWITCHER'; title.Parent=frame
local close=Instance.new('TextButton'); close.Size=UDim2.fromOffset(30,30); close.Position=UDim2.new(1,-36,0,7); close.BackgroundColor3=Color3.fromRGB(80,35,55); close.TextColor3=Color3.new(1,1,1); close.Text='X'; close.Parent=frame; Instance.new('UICorner',close).CornerRadius=UDim.new(0,7)
local status=Instance.new('TextLabel'); status.BackgroundTransparency=1; status.Position=UDim2.fromOffset(10,385); status.Size=UDim2.new(1,-20,0,34); status.Font=Enum.Font.Gotham; status.TextSize=12; status.TextWrapped=true; status.TextColor3=Color3.fromRGB(190,210,240); status.Text='Choose a sky ✨'; status.Parent=frame
local entries={{'Pink Bliss','PinkBliss'},{'Cool Black','CoolBlack'},{'Breakcore','Breakcore'},{'Alya Flushie','AlyaFlushie'},{'Makima','Makima'},{'Nazuna','Nazuna'},{'Alya Sky V3','AlyaV3'},{'Mahiru Poster','MahiruPoster'}}
local function selectSky(name,label)
 state.serial=state.serial+1; local ticket=state.serial; state.active=name
 status.Text='Loading '..label..'...'
 task.spawn(function()
  local a,err=assetsFor(name)
  if state.closed or ticket~=state.serial then return end
  if not a then status.Text='Error: '..tostring(err); warn('[Sky Switcher] '..tostring(err)); return end
  putSky(name); status.Text='Active: '..label..' ✓'
  for _,t in ipairs({.5,1.5,3,6}) do task.delay(t,function() if not state.closed and state.active==name then putSky(name) end end) end
 end)
end
for i,item in ipairs(entries) do
 local b=Instance.new('TextButton'); b.Size=UDim2.new(1,-20,0,37); b.Position=UDim2.fromOffset(10,43+(i-1)*42); b.BackgroundColor3=Color3.fromRGB(58,52,86); b.TextColor3=Color3.new(1,1,1); b.Font=Enum.Font.GothamSemibold; b.TextSize=14; b.Text=item[1]; b.Parent=frame; Instance.new('UICorner',b).CornerRadius=UDim.new(0,8)
 b.MouseButton1Click:Connect(function() selectSky(item[2],item[1]) end)
end
local childConn=Lighting.ChildAdded:Connect(function(obj)
 if state.closed or not state.active or not obj:IsA('Sky') or obj.Name=='FourSkySwitcher_'..state.active then return end
 task.delay(.15,function() if not state.closed then putSky(state.active) end end)
end)
function state.Close()
 if state.closed then return end
 state.closed=true; state.serial=state.serial+1
 childConn:Disconnect(); gui:Destroy()
end
close.MouseButton1Click:Connect(state.Close)
pcall(function() game:GetService('StarterGui'):SetCore('SendNotification',{Title='Sky Switcher V6',Text='Menu loaded! Choose a sky.',Duration=5}) end)
print('[Sky Switcher V6] Ready: Pink Bliss, Cool Black, Breakcore, Alya Flushie, Makima, Nazuna, Alya Sky V3, Mahiru Poster')
